--
-- Table structure for table `cascading_sasaran_opd`
--

CREATE TABLE `cascading_sasaran_opd` (
  `id` int UNSIGNED NOT NULL,
  `opd_id` int UNSIGNED NOT NULL,
  `renstra_indikator_sasaran_id` int UNSIGNED DEFAULT NULL COMMENT 'jangkar Renstra; NULL bila induknya sudah dihapus',
  `iku_indikator_id` int UNSIGNED DEFAULT NULL COMMENT 'jangkar IKU; NULL = belum dipetakan, baris jatuh ke Renstra',
  `source_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'renstra' COMMENT 'renstra | iku - sumber yang dipakai baris ini',
  `parent_id` int UNSIGNED DEFAULT NULL,
  `es3_indikator_id` int UNSIGNED DEFAULT NULL,
  `level` enum('es2','es3','es4','pelaksana') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'jenjang cascading; pelaksana = di bawah Eselon IV/JF',
  `nama_sasaran` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `csf` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

