--
-- Table structure for table `dashboard_status_thresholds`
--

CREATE TABLE `dashboard_status_thresholds` (
  `id` int UNSIGNED NOT NULL,
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'kunci tetap: critical|attention|near_target|achieved|exceeded',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `min_value` decimal(10,2) DEFAULT NULL COMMENT 'batas bawah persentase (inklusif)',
  `max_value` decimal(10,2) DEFAULT NULL COMMENT 'batas atas persentase (inklusif); NULL = tanpa batas atas',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'abu' COMMENT 'slug warna terbatas: merah|oranye|kuning|hijau|biru|abu',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `effective_from` date DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

