--
-- Table structure for table `dokumen_izin_sunting`
--

CREATE TABLE `dokumen_izin_sunting` (
  `id` int UNSIGNED NOT NULL,
  `modul` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'rpjmd | renstra | iku | lakip',
  `scope` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'kabupaten | opd',
  `opd_id` int UNSIGNED DEFAULT NULL,
  `periode_mulai` int NOT NULL,
  `periode_akhir` int NOT NULL,
  `version_id` int UNSIGNED DEFAULT NULL COMMENT 'versi yang berlaku saat izin diminta; untuk jejak',
  `jenis` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'sunting' COMMENT 'sunting = buka kunci; hapus = permohonan menghapus versi',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT 'pending | disetujui | ditolak | selesai | dicabut',
  `alasan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'wajib: mengapa perlu menyunting',
  `catatan_keputusan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'catatan Admin Kabupaten saat menolak/menyetujui',
  `diminta_oleh` int UNSIGNED DEFAULT NULL,
  `diminta_nama` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'dibekukan saat permohonan dibuat',
  `diminta_pada` datetime DEFAULT CURRENT_TIMESTAMP,
  `diputus_oleh` int UNSIGNED DEFAULT NULL,
  `diputus_nama` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `diputus_pada` datetime DEFAULT NULL,
  `selesai_pada` datetime DEFAULT NULL COMMENT 'terisi saat versi berikutnya diajukan',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `opd_key` int UNSIGNED GENERATED ALWAYS AS (coalesce(`opd_id`,0)) STORED,
  `scope_key` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci GENERATED ALWAYS AS (coalesce(`scope`,_utf8mb4'kabupaten')) STORED,
  `aktif_key` tinyint GENERATED ALWAYS AS ((case when (`status` in (_utf8mb4'pending',_utf8mb4'disetujui')) then 1 else NULL end)) STORED
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `dokumen_izin_sunting`
--


-- --------------------------------------------------------

--
-- Table structure for table `dokumen_versi`
--

CREATE TABLE `dokumen_versi` (
  `id` int UNSIGNED NOT NULL,
  `modul` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'rpjmd | renstra | iku | lakip',
  `scope` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'kabupaten' COMMENT 'kabupaten | opd',
  `opd_id` int UNSIGNED DEFAULT NULL COMMENT 'NULL bila scope=kabupaten',
  `periode_mulai` int NOT NULL,
  `periode_akhir` int NOT NULL COMMENT 'untuk modul=lakip: sama dengan periode_mulai (satu tahun)',
  `version_no` int NOT NULL DEFAULT '1' COMMENT 'BUKAN penentu waktu berlaku (§2.6)',
  `label` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'mis. "V3 — Penyesuaian RPJMD Tahun 2026"',
  `effective_from` date NOT NULL COMMENT 'inklusif — SATU-SATUNYA penentu timeline',
  `effective_to` date DEFAULT NULL COMMENT 'EKSKLUSIF; dihitung sistem, bukan diedit user',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'draft' COMMENT 'draft | pending_approval | published | cancelled',
  `copied_from_version_id` int UNSIGNED DEFAULT NULL COMMENT 'deep copy dari versi ini (§10)',
  `mulai_dari_kosong` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = input dari kosong',
  `source_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'rpjmd | renstra | iku — sync IKU (§15) / source LAKIP (§25)',
  `source_version_id` int UNSIGNED DEFAULT NULL,
  `source_captured_at` datetime DEFAULT NULL COMMENT 'terisi = tautan BEKU; sync ulang wajib versi baru (§15)',
