(79, 63, 'Prosentase Gangguan Keamanan, Ketentraman, dan Ketertiban Masyarakat Yang Dapat Diselesaikan', 'Jumlah Laporan Hasil  Sinergitas dengan Kepolisian Negara Republik Indonesia, Tentara Nasional Indonesia dan Instansi Vertikal di Wilayah Kecamatan', 'Laporan masalah X 100 dan hasilnya dibagi dengan target nilai IKM yang telah ditetapkan', '13', 'Kecamatan Pardasuka', 'Camat', 'positif', NULL, 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 03:24:17', '2026-08-27 22:11:54', 'renstra', NULL, 482),
(80, 64, 'Prosentase Pemberdayaan Masyarakat Desa dan Kelurahan', 'Jumlah dokumen yang difasilitasi dalam rangka Perencanaan dan Pengelolaan Keuangan Desa/Kelurahan', 'jumlah kegiatan pembedayaan yang terlaksana / jumlah kegiatan pemberdayaan yang direncanakan X 100%', '13', 'Kecamatan Pardasuka', 'Camat', 'positif', NULL, 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 03:24:17', '2026-08-27 22:11:54', 'renstra', NULL, 483),
(81, 64, 'Prosentase lembaga kemasyarakatan yang difasilitasi', 'Jumlah Laporan Peningkatan Efektifitas kegiatan Pemberdayaan Masyarakat di wilayah Kecamatan', 'Jumlah Laporan Peningkatan Efektifitas pemberdayaan / jumlah lapora peningktan efektifitas yang direncanakan X 100%', '13', 'Kecamatan Pardasuka', 'Camat', 'positif', NULL, 1, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 03:24:17', '2026-09-01 09:23:22', 'renstra', NULL, 485),
(82, 65, 'Jumlah Produksi Ikan', 'Jumlah Produksi Ikan adalah total volume hasil yang diperoleh dari kegiatan penangkapan dan budidaya perikanan, baik dari perairan umum darat maupun tempat pemeliharaan', 'Jumlah Produksi Ikan adalah total volume hasil yang diperoleh dari kegiatan penangkapan dan budidaya perikanan, baik dari perairan umum darat maupun tempat pemeliharaan', '12', 'Bidang Perikanan Budidaya dan Tangkap', 'Kepala Bidang Perikanan Budidaya dan Tangkap', 'positif', '13870', 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 03:26:20', '2026-08-27 22:11:54', 'renstra', NULL, 427),
(83, 66, 'Jumlah Produksi Olahan Ikan', 'Jumlah produksi olahan ikan adalah total berat atau volume produk hasil pengolahan berbahan baku ikan menjadi produk lain yang siap dikonsumsi', 'Jumlah produksi olahan ikan adalah total berat atau volume produk hasil pengolahan berbahan baku ikan menjadi produk lain yang siap dikonsumsi', '12', 'Bidang Pasca Panen dan Pengawasan', 'Kepala Bidang Pasca Panen dan Pengawasan', 'positif', '222,4', 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 03:26:20', '2026-08-27 22:11:54', 'renstra', NULL, 428),
(84, 67, 'Indeks Pembangunan Literasi Masyarakat (IPLM)', 'Pengukuran dalam melakukan pembinaan dan pengembangan perpustakaan sebagai wahana belajar sepanjang hayat untuk mencapai budaya literasi masyarakat.', '(0,30 x Dimensi Kepatuhan) + (0,70 x Dimensi Kinerja) x 100', '19', 'Perpustakaan Nasional RI', 'Kepala Dinas', 'positif', NULL, 0, 'draft', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 03:59:52', '2026-08-27 22:11:54', 'renstra', NULL, 170),
(85, 68, 'Indeks Hasil Pengawasan Kearsipan di lingkup Pemerintahan Daerah', 'Kesesuaian tingkat penyelenggaraan kearsipan daerah dengan prinsip, kaidah, dan standar kearsipan.', '(Nilai Pengawasan Kearsipan Internal x 40%) + (Nilai Pengawasan Kearsipan Eksternal x 60%)', '19', 'Asip Nasional RI', 'Kepala Dinas', 'positif', '58,14', 0, 'draft', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 03:59:52', '2026-08-27 22:11:54', 'renstra', NULL, 171),
