(87, 70, 'Produksi daging', 'jumlah produksi daging per tahun', '∑ produksi daging per tahun', '12', 'Dinas Pertanian', 'Kepala Dinas', 'positif', NULL, 0, 'draft', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:01:37', '2026-08-27 22:11:54', 'renstra', NULL, 175),
