(89, 71, 'Indeks Kualitas Air (IKA)', 'Nilai angka tanpa satuan yang mengambarkan kondisi mutu air permukaan di suatu wilayah pada waktu tertentu', 'Nilai IKA didapatkan dari menjumlahkan nilai perkalian antara bobot setiap bobot parameter dengan nilai sub indeksnya masing - masing', '19', 'Kementrian Lingkungan Hidup dan Kehutanan Direktoral Jendral Pengendalian Pencemaran dan Kerusakan Lingkungan', 'Kepala Dinas Lingkungan Hidup', 'positif', '60.4', 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:04:34', '2026-08-27 22:11:54', 'renstra', NULL, 219);
INSERT INTO `iku_indikator` (`id`, `iku_sasaran_id`, `indikator`, `definisi`, `rumusan_perhitungan`, `satuan`, `sumber_data`, `penanggung_jawab`, `jenis_indikator`, `baseline`, `urutan`, `status`, `revisi_id`, `indikator_sebelumnya_id`, `jenis_perubahan`, `perubahan_substansial`, `berlaku_sampai`, `dihentikan_pada`, `alasan_dihentikan`, `created_at`, `updated_at`, `source_type`, `source_version_id`, `source_indikator_id`) VALUES
(90, 71, 'Indeks Kualitas Udara (IKU)', 'Nilai angka tanpa aturan yang menggambarkan kondisi kebersian atau tingkat Polusi Udara di suatu wilayah pada waktu tertentu', 'Semakin tinggi konsentrasi polutan di bandingkan baku mutunya,maka nilai rata -rata dari tiga indeks parameter pencemaran utama( Nitrogen dioksida, Sulfur dioksida dan partikulat halus)akan semakin besar yang mengakibatkan Nilai IKU semakin kecil( Menunjukan kualitas udara yang menurun)', '19', 'Kementrian Lingkungan Hidup dan Kehutanan Direktoral Jendral Pengendalian Pencemaran dan Kerusakan Lingkungan', 'Kepala Dinas Lingkungan Hidup', 'positif', '84.26', 1, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:04:34', '2026-08-27 22:11:54', 'renstra', NULL, 220),
(91, 71, 'Indeks Kualitas Tutupan Lahan (IKL)', 'Nilai angka tanpa satuan yang mengunakan untuk mengukur kesehatan, mutu dan fungsi ekologis tutupan lahan disuatu wilayah pada waktu tertentu', 'Nilai tutupan lahan di peroleh melalui rata-rata tertimbang dari luas kelas tutupan lahan dengan koefisiennya', '19', 'Kementrian Lingkungan Hidup dan Kehutanan Direktoral Jendral Pengendalian Pencemaran dan Kerusakan Lingkungan', 'Kepala Dinas Lingkungan Hidup', 'positif', '31.81', 2, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:04:34', '2026-08-27 22:11:54', 'renstra', NULL, 221),
(92, 72, 'Nilai Sakip', 'Rangkaian proses manajemen kinerja mulai dari perencanaan, pengukuran, pelaporan, evaluasi, sampai pencapaian sasaran di wilayah\r\nkecamatan', 'Capaian Indikator=Target / Realisasi * 100%', '20', 'Kecamatan\r\nPagelaran\r\nUtara', 'Camat Pagelaran Utara', 'positif', '70', 0, 'draft', NULL, NULL, 'dihentikan', 0, NULL, '2026-08-31 09:04:57', 'Dihapus dari daftar IKU berjalan, tetapi tetap disimpan karena sudah dirujuk dokumen/laporan terdahulu.', '2026-08-13 04:09:10', '2026-08-31 09:04:57', 'renstra', NULL, 414),
(93, 73, 'Indeks Kepuasan Masyarakat (IKM)', 'Nilai kuantitatif dan kualitatif tingkat kepuasan masyarakat terhadap pelayanan di Kecamatan yang diukur melalui 9 unsur pelayanan', 'IKM = Nilai Rata-rata Tertimbang x 25', '13', 'Kecamatan Pagelaran Utara', 'Camat Pagelaran Utara', 'positif', '70', 0, 'draft', NULL, NULL, 'dihentikan', 0, NULL, '2026-08-31 09:05:00', 'Dihapus dari daftar IKU berjalan, tetapi tetap disimpan karena sudah dirujuk dokumen/laporan terdahulu.', '2026-08-13 04:09:10', '2026-08-31 09:05:00', 'renstra', NULL, 516),
(94, 74, 'Persentase partisipasi aktif Masyarakat dalam Perencanaan, Pelaksanaan, dan Pengawasan Program Pemberdayaan', 'Kondisi meningkatnya kapasitas, kemandirian,\r\ndan partisipasi masyarakat desa dan kelurahan\r\ndalam perencanaan, pelaksanaan, pengawasan\r\npembangunan serta pengelolaan kelembagaan dan ekonomi, sehingga mampu menyelesaikan permasalahan secara mandiri dengan dukungan fasilitasi dari Kecamatan', 'ndeks Pemberdayaan Masyarakat Desa/Kelurahan (IPMDK) = [(Skor Kapasitas + Skor Kemandirian + Skor Partisipasi) ÷3] x 100%', '13', 'Kecamatan Pagelaran Utara', 'Camat Pagelaran Utara', 'positif', '99', 0, 'draft', NULL, NULL, 'dihentikan', 0, NULL, '2026-08-31 09:05:02', 'Dihapus dari daftar IKU berjalan, tetapi tetap disimpan karena sudah dirujuk dokumen/laporan terdahulu.', '2026-08-13 04:09:10', '2026-08-31 09:05:02', 'renstra', NULL, 517),
(95, 75, 'Persentase Penurunan Tingkat Gangguan Ketentraman dan Ketertiban Umum yang Terlaporkan dan Tertangani', 'Kondisi aman, tertib, dan kondusif di wilayah\r\nKecamatan yang ditandai dengan menurunnya\r\ngangguan ketentraman dan ketertiban umum,\r\nmeningkatnya kepatuhan hukum masyarakat, serta efektivitas koordinasi Linmas, Satpol PP, dan unsur Forkopimcam dalam pencegahan dan penanganan gangguan', 'Indeks Ketentraman dan Ketertiban Umum Kecamatan (IK3) = [(Skor Pencegahan + Skor Penanganan + Skor Kepatuhan + Skor Kelembagaan) ÷ 4] x 100%', '13', 'Kecamatan Pagelaran Utara', 'Camat Pagelaran Utara', 'positif', '98', 0, 'draft', NULL, NULL, 'dihentikan', 0, NULL, '2026-08-31 09:05:04', 'Dihapus dari daftar IKU berjalan, tetapi tetap disimpan karena sudah dirujuk dokumen/laporan terdahulu.', '2026-08-13 04:09:10', '2026-08-31 09:05:04', 'renstra', NULL, 518),
(96, 76, 'Persentase pelaksanaan tugas-tugas umum pemerintahan oleh Camat dan perangkat Kecamatan', 'Kondisi terselenggaranya tugas-tugas pemerintahan di wilayah Kecamatan secara tertib, sinergis, dan akuntabel', 'Indeks Penyelenggaraan Urusan Pemerintahan Umum Kecamatan\r\n(IPUPK)=[(Skor Tertib + Skor Sinergis + Skor Akuntabel) ÷ 3] x 100%', '13', 'Kecamatan Pagelaran Utara', 'Camat Pagelaran Utara', 'positif', '99', 0, 'draft', NULL, NULL, 'dihentikan', 0, NULL, '2026-08-31 09:05:07', 'Dihapus dari daftar IKU berjalan, tetapi tetap disimpan karena sudah dirujuk dokumen/laporan terdahulu.', '2026-08-13 04:09:10', '2026-08-31 09:05:07', 'renstra', NULL, 519),
(97, 77, 'Persentase peningkatan kualitas tata kelola Pemerintahan Desa berdasarkan hasil pembinaan dan pengawasan', 'Kondisi meningkatnya kualitas penyelenggaraan pemerintahan desa di wilayah Kecamatan yang diwujudkan melalui kegiatan pembinaan,\r\npengawasan, dan fasilitasi yang dilaksanakan', 'Indeks Pembinaan dan Pengawasan Pemerintahan Desa Kecamatan\r\n(IPP2D)=[(Skor Pembinaan + Skor Pengawasan + Skor Fasilitasi) ÷ 3] x 100%', '13', 'Kecamatan Pagelaran Utara', 'Camat Pagelaran Utara', 'positif', '98', 0, 'draft', NULL, NULL, 'dihentikan', 0, NULL, '2026-08-31 09:05:09', 'Dihapus dari daftar IKU berjalan, tetapi tetap disimpan karena sudah dirujuk dokumen/laporan terdahulu.', '2026-08-13 04:09:10', '2026-08-31 09:05:09', 'renstra', NULL, 520),
(98, 78, 'Indeks Kepuasan Masyarakat (IKM)', 'Data dan Informasi tentang Tingkat Kepuasan Masyarakat', 'Nilai survey IKM dikalikan 100 dan hasilnya dibagi dengan target nilai IKM yang ditetapkan.', '13', 'Kecamatan Ambarawa', 'Camat Ambarawa', 'positif', '', 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:22:56', '2026-09-01 09:23:22', 'renstra', NULL, 54),
(99, 78, 'Prosentase Sasaran Penyelenggaraan Urusan Pemerintahan Umum', 'Urusan Pemerintahan yang menjadi Kewenangan Pimpinan dalam Penyelenggaraan Urusan Pemerintahan', '∑ realisasi sasaran penyelenggaraan Urusan Pemerintahan Umum dikalikan 100 dan hasilnya dibagi dengan ∑ target sasaran penyelenggaraan Pemerintahan Umum yang di tetapkan.', '13', 'Kecamatan Ambarawa', 'Camat Ambarawa', 'positif', '', 1, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:22:56', '2026-09-01 09:23:22', 'renstra', NULL, 493),
(100, 79, '\"Persentase Gangguan keamanan, ketentraman dan ketertiban masyarakat yang dapat diselesaikan', 'Segala Bentuk Tindakan yang bertentangan dengan peraturan Perundang-Undangan yang dapat menimbulkan ancaman atau gangguan keamanan, ketentraman dan ketertiban umum di suatu wilayah', '∑ realisasi penyelesaian gangguan trantib dikalikan 100 dan hasilnya dibagi dengan ∑ target penyelesaian gangguan trantib yang di tetapkan.', '13', 'Kecamatan Ambarawa', 'Camat Ambarawa', 'positif', '', 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:22:56', '2026-09-01 09:23:22', 'renstra', NULL, 494),
(101, 80, 'Prosentase Meningkatnya pemberdayaan lembaga kemasyarakatan desa / kelurahan', 'Upaya Peningkatan Kapasitas, peran, dan tugas lembaga Kemasyarakat desa agar mampu tumbuh, berkembang, dan berperan aktif dalam penyelenggaraan pemerintahan, pembangunan, pembinaan kemasayarakatn dan perberdayaan masyarakat desa', '∑ realisasi Pemberdayaan Masyarakat Desa dikalikan 100 dan hasilnya dibagi dengan ∑ target Pemberdayaan Masyarakat Desa yang di tetapkan.', '13', 'Kecamatan Ambarawa', 'Camat Ambarawa', 'positif', '', 0, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:22:56', '2026-09-01 09:23:22', 'renstra', NULL, 495),
(102, 80, 'Prosentase Lembaga Kemasyarakatan yang difasilitasi', 'Lembaga Kemasyarakatan desa/kelurahan yang mendapatkan perlakuan berupa pembinaan, bimbingan, pelatihan,bantuan sarpras dan pendampingan terkait anggaran, agar dapat menjalankan fungsi dan perannya secara efektif', '∑ realisasi pembinaan aparatur pemerintahan kecamatan dikalikan 100 dan hasilnya dibagi dengan ∑ target pembinaan aparatur pemerintahan kecamatan yang di tetapkan.', '13', 'Kecamatan Ambarawa', 'Camat Ambarawa', 'positif', '', 1, 'selesai', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 04:22:56', '2026-09-01 09:23:22', 'renstra', NULL, 496),
(103, 81, 'Level Kapabilitas APIP', 'Pedoman Ukur Perka BPKP 08 Tahun 2021) tentang\r\nPenilaian Kapabilitas Aparat Pengawasan Intern\r\nPemerintah Pada Kementerian/Lembaga/Pemerintah\r\nDaerah', 'Pedoman Ukur Peraturan BPKP Nomor 8 Tahun\r\n2021 tentang penilaian kapabilitas aparat\r\npengawas intern pemerintah pada\r\nkementerian/lembaga/pemerintah daerah', '37', 'Laporan\r\nBPKP', 'Inspektur', 'positif', NULL, 0, 'draft', NULL, NULL, 'tetap', 0, NULL, NULL, NULL, '2026-08-13 06:19:21', '2026-08-27 22:11:54', 'renstra', NULL, 433),
