INSERT INTO `iku_revisi_indikator` (`id`, `revisi_id`, `revisi_sasaran_id`, `sumber_indikator_id`, `indikator`, `definisi`, `rumusan_perhitungan`, `satuan`, `satuan_nama`, `sumber_data`, `penanggung_jawab`, `jenis_indikator`, `baseline`, `urutan`, `status`, `jenis_perubahan`, `indikator_sebelumnya_id`, `perubahan_substansial`, `catatan_perubahan`, `created_at`, `updated_at`, `source_type`, `source_version_id`, `source_ref_id`) VALUES
(9, 3, 9, 1, 'Indeks Pemerintah Digital', 'Indeks Pemerintah Digital (Pemdi) adalah nilai hasil evaluasi tingkat kematangan penyelenggaraan Pemerintah Digital pada pemerintah daerah yang dilakukan oleh Kementerian PANRB berdasarkan aspek Tata Kelola dan Manajemen Pemerintah Digital, Penyelenggara Pemerintah Digital, Data, Keamanan Pemerintah Digital, Teknologi Pemerintah Digital, Keterpaduan Layanan Digital Pemerintah, dan Kepuasan Pengguna Layanan Digital Pemerintah sesuai pedoman evaluasi yang berlaku.', 'Nilai Indeks Pemerintah Digital = Σ (Nilai setiap aspek × Bobot aspek) sesuai metode evaluasi Kementerian PANRB.', '19', 'Indeks', 'Hasil Evaluasi Indeks Pemerintah Digital oleh Kementerian PANRB.', 'Bidang Informasi  Komunikasi Publik Dan Statistik Sektoral, Bidang Tata Kelola Spbe, Persandian Dan Keamanan Informasi', 'positif', '0', 0, 'selesai', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 459),
(10, 4, 10, 13, 'Rasio Konektivitas', 'Perbandingan  jumlah trayek yang terlayani terhadap kebutuhan trayek di suatu wilayah', 'Rasio Konektivitas = (IK1 x bobot angkutan jalan) + (IK2 x bobot angkutan sungai, danau dan penyeberangan)', '40', 'Rasio', 'Dinas Perhubungan', 'Bidang Lalu lintas, Bidang Angkutan dan Teknik Sarana dan Prasarana', 'positif', '0,44', 0, 'draft', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 410),
(11, 5, 11, 14, 'INDEKS PENYELENGGARAAN KETENTRAMAN DAN KETERTIBAN UMUM (IPKKU)', NULL, NULL, '19', 'Indeks', NULL, NULL, 'positif', NULL, 1, 'draft', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 515),
(12, 6, 12, 15, 'Persentase Kepemilikan KTP el', NULL, NULL, '13', '%', NULL, NULL, 'positif', '99,03', 1, 'draft', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 441),
(13, 6, 12, 16, 'Persentase Kepemilikan KIA', NULL, NULL, '13', '%', NULL, NULL, 'positif', '62,56', 2, 'draft', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 442),
(14, 6, 13, 17, 'Persentase Anak Memiliki Akta Lahir 0-18 Th', 'Akta Kelahiran  merupakan dokumen identitas resmi mengenai status dan peristiwa kelahiran anak yang diterbitkan oleh Dinas Kependudukan dan Pencatatan Sipil sekaligus bukti sah pengakuan negara terhadap identitas, silsilah, dan status kewarganegaraan', 'Jumlah anak (0-18 th)memiliki akta kelahiran dibagi Jumlah anak (0-18 th) dikali seratus', '13', '%', 'Ditjen Kependudukan dan Pencatatan Sipil Kemendagri', 'Bidang Pencatatan Sipil', 'positif', '99,76', 0, 'selesai', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 443),
(15, 6, 13, 18, 'Persentase Kepemilikan Dokumen Perkawinan yang dicatatkan', 'Akta Perkawinan adalah dokumen resmi sebagai bukti sahnya perkawinan secara hukum negara', 'Jumlah akta perkawinan yang dicatatkan dibagi Jumlah peristiwa perkawinan (penduduk status kawin) dikali seratus', '13', '%', 'Ditjen Kependudukan dan Pencatatan Sipil Kemendagri', 'Bidang Pencatatan Sipil', 'positif', '47,92', 1, 'draft', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 444),
(16, 6, 13, 19, 'Persentase Kepemilikan Dokumen Perceraian yang dicatatkan', 'Akta Perceraian adalah dokumen resmi yang menjadi bukti sah putusnya ikatan perkawinan antara suami dan istri', 'Jumlah akta perceraian yang dicatatkan', '13', '%', NULL, NULL, 'positif', '66,76', 2, 'draft', 'tetap', NULL, 0, NULL, '2026-08-30 00:33:11', '2026-08-30 00:33:11', 'renstra', NULL, 445),
