INSERT INTO `rpjmd_versi_indikator_sasaran` (`id`, `version_id`, `versi_sasaran_id`, `source_indikator_id`, `copied_from_id`, `indikator_sasaran`, `definisi_op`, `satuan`, `satuan_nama`, `jenis_indikator`, `baseline`, `urutan`, `jenis_perubahan`, `indikator_sebelumnya_id`, `perubahan_substansial`, `catatan_perubahan`, `created_at`, `updated_at`) VALUES
(16, 140, 11, 101, NULL, 'Indeks Pendidikan', 'Indeks Pendidikan adalah indikator yang menggambarkan capaian pembangunan pada dimensi pendidikan, yang diukur berdasarkan rata-rata capaian indikator pendidikan penduduk, yaitu Rata-rata Lama Sekolah (RLS) dan Harapan Lama Sekolah (HLS).', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(17, 140, 12, 102, NULL, 'Indeks Kesehatan', 'Indeks Kesehatan adalah indikator yang menggambarkan capaian pembangunan pada dimensi kesehatan, yang diukur berdasarkan Umur Harapan Hidup saat lahir (UHH) sebagai proksi kondisi kesehatan penduduk.', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(18, 140, 13, 103, NULL, 'Angka Kemiskinan', 'Angka Kemiskinan adalah persentase penduduk yang berada di bawah Garis Kemiskinan pada suatu wilayah dan periode tertentu.\r\n\r\nPenduduk miskin adalah penduduk yang memiliki rata-rata pengeluaran per kapita per bulan di bawah Garis Kemiskinan, baik untuk memenuhi kebutuhan makanan maupun non makanan.', '%', '%', 'indikator negatif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(19, 140, 14, 104, NULL, 'PDRB Perkapita (juta)', 'PDRB per Kapita (juta) adalah rata-rata nilai tambah bruto yang dihasilkan per penduduk dalam suatu wilayah pada periode tertentu, yang diperoleh dari pembagian Produk Domestik Regional Bruto (PDRB) dengan jumlah penduduk, dan dinyatakan dalam juta rupiah.\r\nRumus Perhitungan : Nilai PDRB (Berlaku Atas Dasar Harga Berlaku (ADHB), untuk menggambarkan tingkat kemakmuran nominal, atau\r\nBerlaku Atas Dasar Harga Konstan (ADHK), untuk melihat daya beli riil dan pertumbuhan ekonomi per penduduk) dibagi Jumlah Penduduk', 'Nilai', 'Nilai', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(20, 140, 15, 105, NULL, 'Persentase Pertumbuhan Investasi', 'Persentase Pertumbuhan Investasi adalah besaran peningkatan nilai realisasi investasi pada suatu periode tertentu dibandingkan dengan periode sebelumnya, yang dinyatakan dalam satuan persentase.\r\nPersentase Pertumbuhan Investasi=Realisasi Investasi Tahun n dikurang Realisasi Investasi Tahun (n−1) dibagi Realisasi Investasi Tahun (n−1)​dikali 100%', '%', '%', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(21, 140, 16, 106, NULL, 'Tingkat Pengangguran Terbuka', 'Tingkat Pengangguran Terbuka (TPT) adalah persentase jumlah penganggur terhadap total angkatan kerja pada suatu wilayah dan periode tertentu.\r\nPenganggur adalah penduduk usia kerja yang tidak bekerja, sedang mencari pekerjaan, sedang mempersiapkan usaha, tidak mencari pekerjaan karena merasa tidak mungkin mendapat pekerjaan (putus asa) dan sudah memiliki pekerjaan tetapi belum mulai bekerja.\r\nRumus Perhitungan : Jumlah Penganggur dibagi Jumlah Angkatan Kerja dikali 100 persen.', 'Nilai', 'Nilai', 'indikator negatif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(22, 140, 17, 115, NULL, 'Indeks Reformasi Birokrasi General', 'Indeks Reformasi Birokrasi (RB) General adalah Pembobotan dari Indeks Sakip, Indeks SPBE, Indeks Kualitas Kebijakan, Indeks Pengelolaan Aset dan Indeks Tata Kelola Pengadaan', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(23, 140, 18, 110, NULL, 'Persentase Ketersediaan Pangan terhadap kebutuhan pangan', 'Produksi Padi adalah jumlah hasil panen tanaman padi yang dihasilkan dalam suatu wilayah dan periode tertentu, yang dinyatakan dalam berat gabah kering giling (GKG).\r\n\r\nProduksi padi merupakan hasil perkalian antara luas panen padi dan produktivitas padi per satuan luas.\r\n\r\nRumus Perhitungan : Produksi Padi = Luas Panen Padi dikali Produktivitas Padi', '%', '%', 'indikator positif', NULL, 0, 'baru', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:40:41'),
(28, 140, 19, 107, NULL, 'Indeks Daya Saing Daerah Pilar Infrastruktur', 'Indeks Daya Saing Daerah (IDSD) – Pilar Infrastruktur adalah jumlah skor indikator Rasio Jalan Mantab, Akses Air minum Layak, Akses Sanitasi Layak, dan Rasio Jaringan Irigasi dibagi jumlah seluruh indikator', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(29, 140, 20, 108, NULL, 'Indeks Kualitas Lingkungan Hidup', 'IKLH terdiri dari:Komponen berupa Indeks Kualitas Air (IKA), Indeks Kualitas Udara (IKU), dan Indeks Kualitas Tutupan Lahan (IKTL). IKLH yang dihitung sebagai rata-rata tertimbang dari ketiga indeks tersebut sesuai bobot yang ditetapkan', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(30, 140, 20, 109, NULL, 'Indeks Risiko Bencana', 'Indeks Risiko Bencana (IRB) adalah indikator yang dihitung berdasarkan interaksi antara Tingkat Bahaya (hazard) dikali dengan Kerentanan (vulnerability), dan dibagi Kapasitas (capacity) dalam Menghadapi Bencana', 'Indeks', 'Indeks', 'indikator negatif', NULL, 1, 'tetap', NULL, 0, NULL, '2026-09-17 06:38:29', '2026-09-17 13:38:29'),
(31, 1, 21, 101, NULL, 'Indeks Pendidikan', 'Indeks Pendidikan adalah indikator yang menggambarkan capaian pembangunan pada dimensi pendidikan, yang diukur berdasarkan rata-rata capaian indikator pendidikan penduduk, yaitu Rata-rata Lama Sekolah (RLS) dan Harapan Lama Sekolah (HLS).', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(32, 1, 22, 102, NULL, 'Indeks Kesehatan', 'Indeks Kesehatan adalah indikator yang menggambarkan capaian pembangunan pada dimensi kesehatan, yang diukur berdasarkan Umur Harapan Hidup saat lahir (UHH) sebagai proksi kondisi kesehatan penduduk.', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(33, 1, 23, 103, NULL, 'Angka Kemiskinan', 'Angka Kemiskinan adalah persentase penduduk yang berada di bawah Garis Kemiskinan pada suatu wilayah dan periode tertentu.\r\n\r\nPenduduk miskin adalah penduduk yang memiliki rata-rata pengeluaran per kapita per bulan di bawah Garis Kemiskinan, baik untuk memenuhi kebutuhan makanan maupun non makanan.', '%', '%', 'indikator negatif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(34, 1, 24, 104, NULL, 'PDRB Perkapita (juta)', 'PDRB per Kapita (juta) adalah rata-rata nilai tambah bruto yang dihasilkan per penduduk dalam suatu wilayah pada periode tertentu, yang diperoleh dari pembagian Produk Domestik Regional Bruto (PDRB) dengan jumlah penduduk, dan dinyatakan dalam juta rupiah.\r\nRumus Perhitungan : Nilai PDRB (Berlaku Atas Dasar Harga Berlaku (ADHB), untuk menggambarkan tingkat kemakmuran nominal, atau\r\nBerlaku Atas Dasar Harga Konstan (ADHK), untuk melihat daya beli riil dan pertumbuhan ekonomi per penduduk) dibagi Jumlah Penduduk', 'Nilai', 'Nilai', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(35, 1, 25, 105, NULL, 'Persentase Pertumbuhan Investasi', 'Persentase Pertumbuhan Investasi adalah besaran peningkatan nilai realisasi investasi pada suatu periode tertentu dibandingkan dengan periode sebelumnya, yang dinyatakan dalam satuan persentase.\r\nPersentase Pertumbuhan Investasi=Realisasi Investasi Tahun n dikurang Realisasi Investasi Tahun (n−1) dibagi Realisasi Investasi Tahun (n−1)​dikali 100%', '%', '%', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(36, 1, 26, 106, NULL, 'Tingkat Pengangguran Terbuka', 'Tingkat Pengangguran Terbuka (TPT) adalah persentase jumlah penganggur terhadap total angkatan kerja pada suatu wilayah dan periode tertentu.\r\nPenganggur adalah penduduk usia kerja yang tidak bekerja, sedang mencari pekerjaan, sedang mempersiapkan usaha, tidak mencari pekerjaan karena merasa tidak mungkin mendapat pekerjaan (putus asa) dan sudah memiliki pekerjaan tetapi belum mulai bekerja.\r\nRumus Perhitungan : Jumlah Penganggur dibagi Jumlah Angkatan Kerja dikali 100 persen.', 'Nilai', 'Nilai', 'indikator negatif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(37, 1, 27, 115, NULL, 'Indeks Reformasi Birokrasi General', 'Indeks Reformasi Birokrasi (RB) General adalah Pembobotan dari Indeks Sakip, Indeks SPBE, Indeks Kualitas Kebijakan, Indeks Pengelolaan Aset dan Indeks Tata Kelola Pengadaan', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(38, 1, 28, 110, NULL, 'Persentase Ketersediaan Pangan terhadap kebutuhan pangan', 'Produksi Padi adalah jumlah hasil panen tanaman padi yang dihasilkan dalam suatu wilayah dan periode tertentu, yang dinyatakan dalam berat gabah kering giling (GKG).\r\n\r\nProduksi padi merupakan hasil perkalian antara luas panen padi dan produktivitas padi per satuan luas.\r\n\r\nRumus Perhitungan : Produksi Padi = Luas Panen Padi dikali Produktivitas Padi', '%', '%', 'indikator positif', NULL, 0, 'baru', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(39, 1, 29, 107, NULL, 'Indeks Daya Saing Daerah Pilar Infrastruktur', 'Indeks Daya Saing Daerah (IDSD) – Pilar Infrastruktur adalah jumlah skor indikator Rasio Jalan Mantab, Akses Air minum Layak, Akses Sanitasi Layak, dan Rasio Jaringan Irigasi dibagi jumlah seluruh indikator', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(40, 1, 30, 108, NULL, 'Indeks Kualitas Lingkungan Hidup', 'IKLH terdiri dari:Komponen berupa Indeks Kualitas Air (IKA), Indeks Kualitas Udara (IKU), dan Indeks Kualitas Tutupan Lahan (IKTL). IKLH yang dihitung sebagai rata-rata tertimbang dari ketiga indeks tersebut sesuai bobot yang ditetapkan', 'Indeks', 'Indeks', 'indikator positif', NULL, 0, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14'),
(41, 1, 30, 109, NULL, 'Indeks Risiko Bencana', 'Indeks Risiko Bencana (IRB) adalah indikator yang dihitung berdasarkan interaksi antara Tingkat Bahaya (hazard) dikali dengan Kerentanan (vulnerability), dan dibagi Kapasitas (capacity) dalam Menghadapi Bencana', 'Indeks', 'Indeks', 'indikator negatif', NULL, 1, 'tetap', NULL, 0, NULL, '2026-09-17 07:40:14', '2026-09-17 14:40:14');
