(703, 396, 0, 'Menyusun dan menetapkan SOP pengelolaan keuangan; melaksanakan penatausahaan dan verifikasi keuangan; melakukan pengendalian dan monitoring realisasi anggaran; menyusun dan menyampaikan laporan keuangan tepat waktu.', NULL, '3', '3', '3', '3', 1, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(704, 396, 0, 'Melakukan inventarisasi dan pemutakhiran data aset; menyusun rencana kebutuhan dan pemeliharaan aset; melaksanakan pemeliharaan dan pengamanan aset; menyusun laporan barang milik daerah secara tepat waktu.', NULL, '3', '3', '3', '3', 2, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(705, 396, 0, 'Menyusun kebutuhan pegawai sesuai analisis beban kerja; melaksanakan pengembangan kompetensi ASN; melakukan penilaian kinerja ASN secara objektif; meningkatkan disiplin dan profesionalisme aparatur.', NULL, '3', '3', '3', '3', 3, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(706, 396, 1, 'Meningkatkan pemahaman masyarakat dan generasi muda terhadap nilai-nilai Pancasila melalui sosialisasi, pembinaan, pendidikan, dan kegiatan wawasan kebangsaan.', NULL, '2', '2', '2', '2', 0, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(707, 396, 1, 'Melaksanakan pembinaan karakter masyarakat, khususnya generasi muda, agar memiliki sikap cinta tanah air, toleransi, gotong royong, disiplin, dan bertanggung jawab.', NULL, '2', '2', '2', '2', 1, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(708, 396, 1, 'Meningkatkan wawasan kebangsaan masyarakat melalui kegiatan seminar, dialog, sosialisasi, dan pembinaan mengenai persatuan dan kesatuan bangsa', NULL, '2', '2', '2', '2', 2, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(709, 396, 1, 'Mendorong penerapan nilai toleransi, penghormatan terhadap keberagaman suku, agama, ras, dan antargolongan dalam kehidupan bermasyarakat.', NULL, '2', '2', '2', '2', 3, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(710, 396, 1, 'Melaksanakan kegiatan pembinaan / sosialisasi  generasi muda dalam rangka membentuk generasi yang berkarakter, berwawasan kebangsaan, serta memiliki semangat persatuan dan kesatuan.', NULL, '2', '2', '2', '2', 4, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(711, 396, 1, 'Mendorong partisipasi masyarakat dalam menjaga kerukunan, persatuan, kesatuan, dan keutuhan Negara Kesatuan Republik Indonesia.', NULL, '2', '2', '2', '2', 5, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(712, 396, 1, 'Meningkatkan koordinasi dengan perangkat daerah, lembaga pendidikan, organisasi kemasyarakatan, tokoh agama, tokoh masyarakat, dan unsur terkait dalam pelaksanaan penguatan ideologi Pancasila dan karakter kebangsaan.', NULL, '2', '2', '2', '2', 6, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(713, 396, 3, 'Meningkatkan koordinasi dengan perangkat daerah, instansi vertikal, tokoh masyarakat, tokoh adat, organisasi kemasyarakatan, dan pemangku kepentingan lainnya dalam memperkuat ketahanan ekonomi, sosial, dan budaya.', NULL, '2', '2', '2', '2', 0, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(714, 396, 3, 'Melaksanakan koordinasi dan fasilitasi dalam mengantisipasi serta menangani potensi kerawanan di bidang ekonomi, sosial, dan budaya yang dapat memengaruhi stabilitas daerah.', NULL, '2', '2', '2', '2', 1, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(715, 396, 3, 'Meningkatkan partisipasi masyarakat dalam menjaga ketahanan ekonomi, sosial, dan budaya melalui kegiatan pembinaan, sosialisasi, dialog, dan pemberdayaan masyarakat.', NULL, '2', '2', '2', '2', 2, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(716, 396, 3, 'Mendorong pelestarian nilai-nilai budaya lokal, kearifan lokal, adat istiadat, dan tradisi masyarakat sebagai bagian dari penguatan karakter dan identitas daerah.', NULL, '2', '2', '2', '2', 3, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
(717, 396, 3, 'Meningkatkan upaya pencegahan penyalahgunaan narkotika melalui sosialisasi, edukasi, kampanye, dan pembinaan kepada masyarakat, pelajar, pemuda, serta lingkungan kerja.', NULL, '2', '2', '2', '2', 4, '2026-08-20 08:28:30', '2026-09-14 08:29:47'),
